  1	import { test } from 'node:test';
  2	import assert from 'node:assert/strict';
  3	import * as fs from 'node:fs';
  4	import * as os from 'os';
  5	import * as path from 'node:path';
  6	import { execSync } from 'node:child_process';
  7	import { initializeStorage, writeJsonFile } from '../storage/json-storage.js';
  8	import { RepositoryManager } from '../models/repository/repository.manager.js';
  9	import { ProjectManager } from '../models/project/project.manager.js';
 10	import { WorkspaceManager } from '../models/workspace/workspace.manager.js';
 11	import { WorkspaceOrchestrator } from '../orchestration/workspace-orchestrator.js';
 12	import { RepositoryOrchestrator } from '../orchestration/repository-orchestrator.js';
 13	import { ErrorLogManager } from '../error-log/error-log.manager.js';
 14	import type { AppConfig } from '../config/config.types.js';
 15	import { setupFakeGit, makeTestConfig } from './test-helpers.js';
 16	
 17	// ─── Global fixtures ──────────────────────────────────────────────────────────
 18	
 19	const tmpRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'paralizer-repo-orch-test-'));
 20	const originRepoPath = path.join(tmpRoot, 'origin');
 21	const origin2RepoPath = path.join(tmpRoot, 'origin2');
 22	
 23	process.on('exit', () => {
 24	    fs.rmSync(tmpRoot, { recursive: true, force: true });
 25	});
 26	
 27	/** Creates a simple local git repo with one commit on `main`. */
 28	function buildRepo(dir: string): void {
 29	    fs.mkdirSync(dir, { recursive: true });
 30	    execSync('git init -b main', { cwd: dir });
 31	    execSync('git config user.email "test@test.local"', { cwd: dir });
 32	    execSync('git config user.name "Test"', { cwd: dir });
 33	    fs.writeFileSync(path.join(dir, 'README.md'), `hello from ${path.basename(dir)}`);
 34	    execSync('git add .', { cwd: dir });
 35	    execSync('git commit -m "initial"', { cwd: dir });
 36	}
 37	
 38	buildRepo(originRepoPath);
 39	buildRepo(origin2RepoPath);
 40	
 41	// ─── Helpers ──────────────────────────────────────────────────────────────────
 42	
 43	function makeTempDir(): string {
 44	    return fs.mkdtempSync(path.join(tmpRoot, 'test-'));
 45	}
 46	
 47	
 48	
 49	interface TestFixture {
 50	    config: AppConfig;
 51	    repoManager: RepositoryManager;
 52	    projectManager: ProjectManager;
 53	    workspaceManager: WorkspaceManager;
 54	    workspaceOrchestrator: WorkspaceOrchestrator;
 55	    orchestrator: RepositoryOrchestrator;
 56	    projectId: string;
 57	}
 58	
 59	/**
 60	 * Creates a fixture with:
 61	 * - One project ('test-project') containing 'repo-a'
 62	 * - A STABLE workspace already cloned via WorkspaceOrchestrator
 63	 */
 64	async function makeFixture(base: string): Promise<TestFixture> {
 65	    const config = makeTestConfig(base);
 66	    initializeStorage(config);
 67	
 68	    const repoManager = new RepositoryManager(config);
 69	    const projectManager = new ProjectManager(config, repoManager);
 70	    const workspaceManager = new WorkspaceManager(projectManager);
 71	    const workspaceOrchestrator = new WorkspaceOrchestrator(config, projectManager, workspaceManager, repoManager);
 72	    const orchestrator = new RepositoryOrchestrator(config, projectManager, repoManager);
 73	
 74	    repoManager.add({ url: originRepoPath, id: 'repo-a' });
 75	    repoManager.add({ url: origin2RepoPath, id: 'repo-b' });
 76	
 77	    projectManager.create('Test Project', ['repo-a'], undefined, 'test-project');
 78	
 79	    // Clone repo-a into STABLE workspace
 80	    await workspaceOrchestrator.createWorkspace('test-project', 'STABLE');
 81	
 82	    return { config, repoManager, projectManager, workspaceManager, workspaceOrchestrator, orchestrator, projectId: 'test-project' };
 83	}
 84	
 85	// ─── addRepositoryToProject ───────────────────────────────────────────────────
 86	
 87	test('addRepositoryToProject clones the repository into the existing workspace', async () => {
 88	    const { config, orchestrator, projectId } = await makeFixture(makeTempDir());
 89	    await orchestrator.addRepositoryToProject(projectId, 'repo-b');
 90	
 91	    const clonePath = path.join(config.projectsFolder, projectId, 'STABLE', 'repo-b');
 92	    assert.ok(fs.existsSync(path.join(clonePath, '.git')), 'repo-b should be cloned in STABLE workspace');
 93	});
 94	
 95	test('addRepositoryToProject clones into all existing workspaces', async () => {
 96	    const base = makeTempDir();
 97	    const { config, orchestrator, workspaceManager, workspaceOrchestrator, projectId } = await makeFixture(base);
 98	
 99	    // Add a second workspace (DEV)
100	    workspaceManager.create(projectId, 'DEV');

  1	/**
  2	 * Tests for WP-010: GUI Credential-Missing Error Display.
  3	 *
  4	 * Acceptance Criteria verified:
  5	 *   AC1 — When a repository's clone error contains the credential-missing
  6	 *          sentinel text ("requires a credential for host"), the workspace
  7	 *          detail view shows a "Missing Credential" badge instead of the
  8	 *          generic "No data" badge.
  9	 *   AC2 — The "Missing Credential" badge links to the repository detail view
 10	 *          (#/repositories/:id) where the user can select a credential.
 11	 *   AC3 — Non-credential clone errors continue to display as the generic
 12	 *          "No data" badge (no regression in existing error display).
 13	 *   AC4 — The credential-missing error detection uses the sentinel text
 14	 *          ("requires a credential for host") from the orchestrator error
 15	 *          messages (WP-007).
 16	 *
 17	 * Additional toast message tests:
 18	 *   T1  — When all failures are credential-related, the toast mentions
 19	 *          "credential errors" and the affected repository IDs.
 20	 *   T2  — When failures are a mix of credential and non-credential, the
 21	 *          toast distinguishes them.
 22	 *   T3  — When all failures are non-credential, the original toast message
 23	 *          is shown unchanged.
 24	 *
 25	 * Uses Node's built-in test runner with jsdom for a minimal DOM environment.
 26	 * Run individually with:
 27	 *   node --test gui/public/js/views/workspace-detail.credential-error.test.mjs
 28	 */
 29	
 30	import { test, beforeEach } from 'node:test';
 31	import assert from 'node:assert/strict';
 32	import { JSDOM } from 'jsdom';
 33	
 34	// ---------------------------------------------------------------------------
 35	// jsdom setup — install globals before any module is loaded
 36	// ---------------------------------------------------------------------------
 37	
 38	const dom = new JSDOM(
 39	    '<!DOCTYPE html><html><body><div id="toast-container"></div><div id="app"></div></body></html>',
 40	    { url: 'http://localhost/' },
 41	);
 42	
 43	const { window } = dom;
 44	
 45	globalThis.document    = window.document;
 46	globalThis.window      = window;
 47	globalThis.location    = window.location;
 48	globalThis.HTMLElement = window.HTMLElement;
 49	globalThis.CSS = window.CSS ?? { escape: (s) => s.replace(/["\\]/g, '\\$&') };
 50	
 51	// Stub setInterval / clearInterval so the polling loop never fires and the
 52	// process exits cleanly after tests complete.
 53	let _intervalId = 0;
 54	const _intervals = new Map();
 55	globalThis.setInterval = (fn, delay) => {
 56	    const id = ++_intervalId;
 57	    _intervals.set(id, { fn, delay });
 58	    return id;
 59	};
 60	globalThis.clearInterval = (id) => {
 61	    _intervals.delete(id);
 62	};
 63	
 64	// ---------------------------------------------------------------------------
 65	// Minimal fetch mock (required by api.js)
 66	// ---------------------------------------------------------------------------
 67	
 68	globalThis.fetch = async () => ({
 69	    status: 200,
 70	    ok: true,
 71	    statusText: 'OK',
 72	    headers: { get: () => 'application/json' },
 73	    json: async () => ({}),
 74	});
 75	
 76	// ---------------------------------------------------------------------------
 77	// Import dependencies and patch api
 78	// ---------------------------------------------------------------------------
 79	
 80	const { api } = await import('../api.js');
 81	
 82	// Credential-missing sentinel — must match CREDENTIAL_MISSING_SENTINEL in
 83	// workspace-detail.js and the error message template in the orchestrators.
 84	const SENTINEL = 'requires a credential for host';
 85	
 86	// Setup spy — controls what the API returns after workspace setup.
 87	const setupCalls = [];
 88	let setupResult  = { results: [] };
 89	api.workspaces.setup = async (projectId, wid) => {
 90	    setupCalls.push({ projectId, wid });
 91	    return setupResult;
 92	};
 93	
 94	// Default stubs for the remaining api calls used by renderWorkspaceDetail.
 95	api.workspaces.get    = async () => ({
 96	    Id: 'DEV', id: 'DEV', Description: '', initialized: false, folderPath: '/tmp/dev',
 97	});
 98	api.workspaces.health = async () => ({ healthy: true, issues: [] });
 99	api.workspaces.launch = api.workspaces.launch || {};
100	api.workspaces.launch.githubDesktop = async () => ({ success: true });

101	    await workspaceOrchestrator.createWorkspace(projectId, 'DEV');
102	
103	    await orchestrator.addRepositoryToProject(projectId, 'repo-b');
104	
105	    const stablePath = path.join(config.projectsFolder, projectId, 'STABLE', 'repo-b');
106	    const devPath = path.join(config.projectsFolder, projectId, 'DEV', 'repo-b');
107	    assert.ok(fs.existsSync(path.join(stablePath, '.git')), 'repo-b should be cloned in STABLE');
108	    assert.ok(fs.existsSync(path.join(devPath, '.git')), 'repo-b should be cloned in DEV');
109	});
