111	test('addRepositoryToProject updates VS Code workspace file to include new repo', async () => {
112	    const { config, orchestrator, projectId } = await makeFixture(makeTempDir());
113	    await orchestrator.addRepositoryToProject(projectId, 'repo-b');
114	
115	    const wsFile = path.join(config.projectsFolder, projectId, `${projectId}-STABLE.code-workspace`);
116	    const parsed = JSON.parse(fs.readFileSync(wsFile, 'utf8'));
117	    const repoPaths = parsed.folders.map((f: { path: string }) => f.path);
118	
119	    const expectedRepoB = path.join(config.projectsFolder, projectId, 'STABLE', 'repo-b');
120	    assert.ok(repoPaths.includes(expectedRepoB), 'VS Code workspace file should include repo-b path');
121	});
122	
123	test('addRepositoryToProject updates project data to include new repo', async () => {
124	    const { orchestrator, projectManager, projectId } = await makeFixture(makeTempDir());
125	    await orchestrator.addRepositoryToProject(projectId, 'repo-b');
126	
127	    const project = projectManager.getById(projectId)!;
128	    assert.ok(project.Repositories.includes('repo-b'), 'repo-b should be in project repositories');
129	});
130	
131	test('addRepositoryToProject returns per-workspace clone results', async () => {
132	    const { orchestrator, projectId } = await makeFixture(makeTempDir());
133	    const result = await orchestrator.addRepositoryToProject(projectId, 'repo-b');
134	
135	    assert.ok(Array.isArray(result.workspaceResults), 'should return workspaceResults array');
136	    assert.strictEqual(result.workspaceResults.length, 1, 'one workspace result for STABLE');
137	    assert.strictEqual(result.workspaceResults[0].workspaceId, 'STABLE');
138	    assert.strictEqual(result.workspaceResults[0].success, true);
139	});
