141	test('addRepositoryToProject captures failure for unreachable repo without aborting', async () => {
142	    const base = makeTempDir();
143	    const config = makeTestConfig(base);
144	    initializeStorage(config);
145	
146	    const repoManager = new RepositoryManager(config);
147	    const projectManager = new ProjectManager(config, repoManager);
148	    const workspaceManager = new WorkspaceManager(projectManager);
149	    const workspaceOrchestrator = new WorkspaceOrchestrator(config, projectManager, workspaceManager, repoManager);
150	    const orchestrator = new RepositoryOrchestrator(config, projectManager, repoManager);
151	
152	    repoManager.add({ url: originRepoPath, id: 'repo-a' });
153	    repoManager.add({ url: '/nonexistent/bad-repo', id: 'bad-repo' });
154	
155	    projectManager.create('Test Project', ['repo-a'], undefined, 'test-project');
